/// FigCraft Plus: create a `slot` style from `value` (the Local styles "+" menu) and open its
/// editor at screen y `y` with the new name selected for typing.
pub(crate) fn create_local(app: &mut FigApp, slot: StyleSlot, value: Value, y: f32) {
    let Some(name) = app.session.doc().ok().map(|d| next_name(d, slot.default_name())) else { return };
    let made = app.run("style.create", json!({"type": slot.create_type(), "name": name, "value": value}));
    if let Some(id) = made.as_ref().and_then(|v| v["id"].as_str()) {
        let edit = Some(Editing { id: id.to_string(), name, description: String::new(), focus: true });
        app.ui.style_picker = Some(Picker { slot, ids: Vec::new(), y, query: String::new(), edit });
    }
}
